/bin/bash -lc "python - <<'PY'
import requests
for repo in ['seqkit','samtools','bwa','bbmap','mash']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/'
    try:
        r=requests.get(url, params={'limit':5,'onlyActiveTags':'true'}, timeout=20)
        print('##', repo, r.status_code)
        if r.ok:
            for t in r.json().get('tags',[])[:5]: print(t.get('name'))
    except Exception as e: print(repo,e)
PY"

